#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader backdrop;
float4 amzSample_comp(float2 uv) { return float4(backdrop.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_comp(uv);return float4(0.0); }
uniform float amzp_bmMode;
uniform float amzp_opacity;
uniform float amzp_strength;
uniform float amzp_swapLayers;
uniform float amzp_invertLayer;
uniform float amzp_keepMode;
uniform float amzp_saturation;
uniform float amzp_linearBlend;
uniform float amzp_useR;
uniform float amzp_useG;
uniform float amzp_useB;
uniform float amzp_topLow;
uniform float amzp_topHigh;
uniform float amzp_botLow;
uniform float amzp_botHigh;
uniform float amzp_ifSoft;
        float lumC(float3 c) { return dot(c, float3(0.3, 0.59, 0.11)); }
        float burnF(float b, float t) {
            if (b >= 1.0) return 1.0;
            if (t <= 0.0) return 0.0;
            return 1.0 - min(1.0, (1.0 - b) / t);
        }
        float dodgeF(float b, float t) {
            if (b <= 0.0) return 0.0;
            if (t >= 1.0) return 1.0;
            return min(1.0, b / (1.0 - t));
        }
        float hardF(float b, float t) {
            return t <= 0.5 ? 2.0 * b * t : 1.0 - 2.0 * (1.0 - b) * (1.0 - t);
        }
        float softF(float b, float t) {
            if (t <= 0.5) return b - (1.0 - 2.0 * t) * b * (1.0 - b);
            float d = b <= 0.25 ? ((16.0 * b - 12.0) * b + 4.0) * b : sqrt(b);
            return b + (2.0 * t - 1.0) * (d - b);
        }
        float vividF(float b, float t) {
            return t < 0.5 ? burnF(b, 2.0 * t) : dodgeF(b, 2.0 * t - 1.0);
        }
        float pinF(float b, float t) {
            return t < 0.5 ? min(b, 2.0 * t) : max(b, 2.0 * t - 1.0);
        }
        float3 burn3(float3 b, float3 t) { return float3(burnF(b.r, t.r), burnF(b.g, t.g), burnF(b.b, t.b)); }
        float3 dodge3(float3 b, float3 t) { return float3(dodgeF(b.r, t.r), dodgeF(b.g, t.g), dodgeF(b.b, t.b)); }
        float3 hard3(float3 b, float3 t) { return float3(hardF(b.r, t.r), hardF(b.g, t.g), hardF(b.b, t.b)); }
        float3 soft3(float3 b, float3 t) { return float3(softF(b.r, t.r), softF(b.g, t.g), softF(b.b, t.b)); }
        float3 vivid3(float3 b, float3 t) { return float3(vividF(b.r, t.r), vividF(b.g, t.g), vividF(b.b, t.b)); }
        float3 pin3(float3 b, float3 t) { return float3(pinF(b.r, t.r), pinF(b.g, t.g), pinF(b.b, t.b)); }
        float3 blendDark(float3 b, float3 t) {
            if (int(amzp_bmMode) == 0) return min(b, t);
            if (int(amzp_bmMode) == 1) return b * t;
            if (int(amzp_bmMode) == 2) return burn3(b, t);
            if (int(amzp_bmMode) == 3) return max(b + t - 1.0, 0.0);
            return lumC(t) < lumC(b) ? t : b;
        }
        float3 blendLight(float3 b, float3 t) {
            if (int(amzp_bmMode) == 5) return max(b, t);
            if (int(amzp_bmMode) == 6) return b + t - b * t;
            if (int(amzp_bmMode) == 7) return dodge3(b, t);
            if (int(amzp_bmMode) == 8) return min(b + t, 1.0);
            return lumC(t) > lumC(b) ? t : b;
        }
        float3 blendContrast(float3 b, float3 t) {
            if (int(amzp_bmMode) == 10) return hard3(t, b);
            if (int(amzp_bmMode) == 11) return soft3(b, t);
            if (int(amzp_bmMode) == 12) return hard3(b, t);
            if (int(amzp_bmMode) == 13) return vivid3(b, t);
            if (int(amzp_bmMode) == 14) return clamp(b + 2.0 * t - 1.0, 0.0, 1.0);
            if (int(amzp_bmMode) == 15) return pin3(b, t);
            return step(1.0, b + t);
        }
        float satC(float3 c) { return max(max(c.r, c.g), c.b) - min(min(c.r, c.g), c.b); }
        float3 setSat(float3 c, float s) {
            float mn = min(min(c.r, c.g), c.b);
            float d = max(max(c.r, c.g), c.b) - mn;
            if (d <= 0.00001) return float3(0.0);
            return (c - mn) * s / d;
        }
        float divF(float b, float t) {
            if (b <= 0.0) return 0.0;
            if (t <= 0.0) return 1.0;
            return min(1.0, b / t);
        }
        float hash12(float2 p) {
            float3 q = fract(float3(p.xyx) * 0.1031);
            q += dot(q, q.yzx + 33.33);
            return fract((q.x + q.y) * q.z);
        }
        float3 clipColor(float3 c) {
            float l = lumC(c);
            float n = min(min(c.r, c.g), c.b);
            float x = max(max(c.r, c.g), c.b);
            if (n < 0.0) c = l + (c - l) * l / max(l - n, 0.0001);
            if (x > 1.0) c = l + (c - l) * (1.0 - l) / max(x - l, 0.0001);
            return c;
        }
        float3 setLum(float3 c, float l) {
            return clipColor(c + (l - lumC(c)));
        }
        float3 blendOther(float3 b, float3 t) {
            if (int(amzp_bmMode) == 17) return abs(b - t);
            if (int(amzp_bmMode) == 18) return b + t - 2.0 * b * t;
            if (int(amzp_bmMode) == 19) return max(b - t, 0.0);
            if (int(amzp_bmMode) == 20) return float3(divF(b.r, t.r), divF(b.g, t.g), divF(b.b, t.b));
            if (int(amzp_bmMode) == 21) return setLum(setSat(t, satC(b)), lumC(b));
            if (int(amzp_bmMode) == 22) return setLum(setSat(b, satC(t)), lumC(b));
            if (int(amzp_bmMode) == 23) return setLum(t, lumC(b));
            if (int(amzp_bmMode) == 24) return setLum(b, lumC(t));
            return t;
        }
        float inRange(float v, float lo, float hi, float s) {
            float sf = max(s, 0.0001);
            return smoothstep(lo - sf, lo, v) * (1.0 - smoothstep(hi, hi + sf, v));
        }
        void amzRender() {
            float4 src = amzTexture(0, amzScreenNorm());
            float4 dst = amzTexture(1, amzScreenNorm());
            float a = src.a;
            if (a <= 0.0001) {
                amzOutput = float4(0.0);
                return;
            }
            float3 amzLocal_layer = clamp(src.rgb / a, 0.0, 1.0);
            float3 back = dst.a > 0.0001 ? clamp(dst.rgb / dst.a, 0.0, 1.0) : float3(0.0);
            float3 t = (amzp_invertLayer>0.5) ? 1.0 - amzLocal_layer : amzLocal_layer;
            float3 b = back;
            if ((amzp_swapLayers>0.5)) {
                float3 k = t;
                t = b;
                b = k;
            }
            if ((amzp_linearBlend>0.5)) {
                t = pow(t, float3(2.2));
                b = pow(b, float3(2.2));
            }
            float3 r;
            if (int(amzp_bmMode) < 5) r = blendDark(b, t);
            else if (int(amzp_bmMode) < 10) r = blendLight(b, t);
            else if (int(amzp_bmMode) < 17) r = blendContrast(b, t);
            else r = blendOther(b, t);
            r = clamp(r, 0.0, 1.0);
            if ((amzp_linearBlend>0.5)) r = pow(r, float3(1.0 / 2.2));
            r = clamp(back + (r - back) * amzp_strength, 0.0, 1.0);
            if (int(amzp_keepMode) == 1) r = setLum(back, lumC(r));
            else if (int(amzp_keepMode) == 2) r = setLum(r, lumC(back));
            r = clamp(mix(float3(lumC(r)), r, amzp_saturation), 0.0, 1.0);
            r = mix(back, r, float3((amzp_useR>0.5) ? 1.0 : 0.0, (amzp_useG>0.5) ? 1.0 : 0.0, (amzp_useB>0.5) ? 1.0 : 0.0));
            float w = inRange(lumC(amzLocal_layer), amzp_topLow, amzp_topHigh, amzp_ifSoft) * inRange(lumC(back), amzp_botLow, amzp_botHigh, amzp_ifSoft);
            r = mix(back, r, w);
            r = mix(amzLocal_layer, r, clamp(dst.a, 0.0, 1.0));
            float o = a * clamp(amzp_opacity, 0.0, 1.0);
            if (int(amzp_bmMode) == 25) o = hash12(floor(float4(amzCoord.x/1.0,(screen.w-amzCoord.y)/1.0,0.0,1.0).xy)) < o ? 1.0 : 0.0;
            amzOutput = float4(r * o, o);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
